28: // "maximum output tokens (65536)", "at most 32768", "no more than 8192",
29: // "exceeds the maximum allowed value of 4096" (OpenRouter), "greater than the
30: // maximum 16384" (Fireworks), "must be less than 8192" (DeepInfra). No bare
31: // "exceeds N" or "less than N": those read any number in the message ("input
32: // tokens exceeds 200", "exceeds 30000 TPM").
33: const CEILING_PHRASE = '(?:less than or equal to|must be less than|at most|no (?:more|greater) than|(?:cannot|must not|can not) exceed|greater than the maximum|maximum output tokens|maximum allowed value|max output tokens|maximum value|output limit|maximum is)\\W{0,4}(?:of\\s+)?\\W{0,2}(\\d{3,7})';
