271: async function workerLoop() {
272:   for (;;) {
273:     const job = state.jobs.find(j => j.status === 'queued');
274:     if (!job) { await sleep(800); continue; }
275:     job.status = 'running'; job.startedAt = Date.now(); saveState();
276:     log('Job gestartet', job.id.slice(0, 8), '@' + job.route, 'channel', job.channel);
277:     try {
278:       const answer = await runOpencode(job);
279:       job.status = 'done'; job.answer = answer.slice(0, 8000); job.finishedAt = Date.now();
280:       log('Job fertig', job.id.slice(0, 8));
281:       if (job.notify) await deliver(job.chatId, answer, job.replyTo);
282:     } catch (e) {
283:       const errMsg = String(e && (e.message || e) || '').slice(0, 1200);
284:       if (isContextOverflowError(errMsg)) {
285:         saveHandoff(job, 'context_overflow', errMsg);
286:         delete state.sessions[job.route];
287:         state.msgCounts[job.route] = 0;
288:         job.status = 'failed'; job.error = 'Kontextlimit erreicht - Stand gespeichert, neuer Versuch in frischer Session.'; job.finishedAt = Date.now();
289:         const prev = (state.handoffs && state.handoffs[job.route]) ? ('\n\n--- Gesicherter Stand (automatisch) ---\n' + state.handoffs[job.route].slice(0, 2500)) : '';
