292:         log('Auto-Weiterarbeit nach Kontextlimit', job.id.slice(0,8), '->', retryJob.id.slice(0,8));
293:       } else {
294:         job.status = 'failed'; job.error = errMsg.slice(0, 400); job.finishedAt = Date.now();
295:         log('Job FEHLGESCHLAGEN', job.id.slice(0, 8), job.error);
296:         if (job.notify) await deliver(job.chatId, '❌ Fehler: ' + job.error, job.replyTo);
297:         delete state.sessions[job.route];
298:       }
299:     }
300:     bumpMsgCount(job.route);
301:     saveState();
302:   }
303: }
