314: function serveStatic(res, urlPath) {
315:   const rel = urlPath === '/' ? '/index.html' : urlPath.split('?')[0];
316:   const file = path.normalize(path.join(PUBLIC, rel));
317:   if (!file.startsWith(PUBLIC)) { res.writeHead(404); res.end('not found'); return; }
318:   fs.readFile(file, (err, data) => {
319:     if (err) { res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' }); res.end('not found'); return; }
320:     res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream', 'Cache-Control': path.extname(file) === '.html' ? 'no-store' : 'max-age=3600' });
321:     res.end(data);
322:   });
323: }
