220: function runOpencode(job) {
221:   return new Promise((resolve, reject) => {
222:     const routeDef = CFG.routes[job.route] || CFG.routes.default;
223:     const dirAbs = path.isAbsolute(routeDef.dir) ? routeDef.dir : path.join(CFG.workspace, routeDef.dir || '.');
224:     const cwd = fs.existsSync(dirAbs) ? dirAbs : CFG.workspace;
225:     const session = state.sessions[job.route] || '';
226: 
227:     const args = ['run', '--format', 'json'];
228:     if (CFG.opencode?.auto !== false) args.push('--auto');
229:     if (routeDef.model) args.push('--model', routeDef.model);
230:     if (session) args.push('--session', session);
231:     args.push('--title', String(job.text || '').slice(0, 60) || 'AI-SYSTEM');
232:     args.push(String(job.text || ''));
233: 
234:     const child = spawn(CFG.opencodeExe, args, {
235:       cwd, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'],
236:       env: { ...process.env, OPENCODE_CONFIG: CFG.opencodeConfig }
237:     });
238: 
239:     let settled = false, stdout = '', stderr = '';
240:     const tokens = setTimeout(() => {
241:       if (settled) return; settled = true;
242:       try { spawn('taskkill', ['/PID', String(child.pid), '/T', '/F'], { windowsHide: true }); } catch { child.kill('SIGKILL'); }
243:       reject(new Error(`opencode Timeout nach ${CFG.routeTimeoutSec}s`));
244:     }, (CFG.routeTimeoutSec || 900) * 1000);
245:     child.unref?.();
246: 
247:     child.stdout.on('data', d => stdout += d);
248:     child.stderr.on('data', d => stderr += d);
249:     child.on('error', e => { if (settled) return; settled = true; clearTimeout(tokens); reject(e); });
250:     child.on('close', code => {
251:       if (settled) return; settled = true; clearTimeout(tokens);
252:       let newSession = '', texts = [];
253:       for (const line of stdout.split(/\r?\n/)) {
254:         const l = line.trim();
255:         if (!l.startsWith('{')) continue;
256:         try {
257:           const ev = JSON.parse(l);
258:           if (ev.sessionID && !newSession) newSession = String(ev.sessionID);
259:           if (ev.type === 'text' && ev.part && typeof ev.part.text === 'string') texts.push(ev.part.text);
260:         } catch { /* kein json */ }
261:       }
262:       if (newSession) state.sessions[job.route] = newSession;
263:       const answer = texts.join('').trim();
264:       if (code !== 0) { reject(new Error(`opencode exit ${code}: ${(stderr || stdout).slice(0, 300)}`)); return; }
265:       if (!answer) { reject(new Error('opencode lieferte keinen Text (' + stdout.trim().slice(0, 160) + ')')); return; }
266:       resolve(answer);
267:     });
268:   });
269: }
