async function deliver(chatId, text, replyTo) {
  const clean = String(text || '').trim() || '(leere Antwort)';
  const buf = Buffer.from(clean, 'utf8');
  const totalBytes = buf.length;
  const MAX = 4096;
  const chunks = [];
  for (let off = 0; off < totalBytes; off += MAX) {
    chunks.push(buf.subarray(off, off + MAX));
  }
  const chunkCount = chunks.length;
  for (let i = 0; i < chunkCount; i++) {
    let payload = '';
    if (chunkCount > 1) {
      // Ersten Byte-Chunk sicher in UTF-8 decoden; Rest als Buffer direkt ansenden via raw send nicht möglich – also alles über Text-Kanal
      // Wir encodieren jeden Chunk einzeln und senden als Text, weil Telegram sendMessage nur Text akzeptiert.
      // Header für Fortsetzungen: "(Fortsetzung k/N)" – ASCII-safe Prefix.
      const prefix = i === 0 ? '' : `(Fortsetzung ${i + 1}/${chunkCount})\n`;
      try {
        payload = prefix + chunks[i].toString('utf8');
      } catch {
        payload = prefix + '[unkorrigierbarer Chunk]';
      }
    } else {
      payload = chunks[i].toString('utf8');
    }
    try {
      await tgApi('sendMessage', { chat_id: chatId, text: payload, ...(replyTo ? { reply_to_message_id: replyTo } : {}) }, 20000);
    } catch (e) { log('SEND-FAIL', e.message); }
    if (i < chunkCount - 1) await sleep(300);
  }
}

