242: function runOpencode(job) {
243:   return new Promise((resolve, reject) => {
244:     const routeDef = CFG.routes[job.route] || CFG.routes.default;
245:     const dirAbs = path.isAbsolute(routeDef.dir) ? routeDef.dir : path.join(CFG.workspace, routeDef.dir || '.');
246:     const cwd = fs.existsSync(dirAbs) ? dirAbs : CFG.workspace;
247:     const session = state.sessions[job.route] || '';
248: 
249:     const args = ['run', '--format', 'json'];
250:     if (CFG.opencode?.auto !== false) args.push('--auto');
251:     if (routeDef.model) args.push('--model', routeDef.model);
252:     if (session) args.push('--session', session);
253:     args.push('--title', String(job.text || '').slice(0, 60) || 'AI-SYSTEM');
254:     args.push(String(job.text || ''));
255: 
256:     const child = spawn(CFG.opencodeExe, args, {
257:       cwd, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'],
258:       env: { ...process.env, OPENCODE_CONFIG: CFG.opencodeConfig }
259:     });
260: 
261:     let settled = false, stdout = '', stderr = '';
262:     const tokens = setTimeout(() => {
263:       if (settled) return; settled = true;
264:       try { spawn('taskkill', ['/PID', String(child.pid), '/T', '/F'], { windowsHide: true }); } catch { child.kill('SIGKILL'); }
265:       reject(new Error(`opencode Timeout nach ${CFG.routeTimeoutSec}s`));
266:     }, (CFG.routeTimeoutSec || 900) * 1000);
267:     child.unref?.();
268: 
269:     child.stdout.on('data', d => stdout += d);
270:     child.stderr.on('data', d => stderr += d);
271:     child.on('error', e => { if (settled) return; settled = true; clearTimeout(tokens); reject(e); });
272:     child.on('close', code => {
273:       if (settled) return; settled = true; clearTimeout(tokens);
274:       let newSession = '', texts = [];
275:       for (const line of stdout.split(/\r?\n/)) {
276:         const l = line.trim();
277:         if (!l.startsWith('{')) continue;
278:         try {
279:           const ev = JSON.parse(l);
280:           if (ev.sessionID && !newSession) newSession = String(ev.sessionID);
281:           if (ev.type === 'text' && ev.part && typeof ev.part.text === 'string') texts.push(ev.part.text);
282:         } catch { /* kein json */ }
283:       }
284:       if (newSession) state.sessions[job.route] = newSession;
285:       const answer = texts.join('').trim();
286:       if (code !== 0) { reject(new Error(`opencode exit ${code}: ${(stderr || stdout).slice(0, 300)}`)); return; }
287:       if (!answer) { reject(new Error('opencode lieferte keinen Text (' + stdout.trim().slice(0, 160) + ')')); return; }
288:       resolve(answer);
289:     });
290:   });
291: }
