/* ===================== Telegram-Mediapipeline (Zero-Dep) =====================
 * Download: Bot-API file_path → rohes GET api.telegram.org/bot<TOKEN>/file/bot/<file_path>
 * Storage:  07_Recherche/Telegram-Medien/{photos,videos,documents}/ + 09_Prompts/Telegram-Voice/
 * Re-Send:  manuelle multipart/form-data (photo/video/document) + caption mit Speicherpfad.
 * Voice:    Download als .ogg; Transkription erst nach Boss-Grundsatzentscheidung
 *           (lokale Whisper/ffmpeg-Pipeline – noch nicht eingebunden).
 * ============================================================ */
// Schritt 1: Dateiname aus Telegram-Filename bzw. file_id ableiten, alphanumerisch sanitisieren.
function _mediaFilename(file, fallbackExt) {
  const base = (file.filename || file.file_unique_id || Date.now().toString(36)).replace(/[^\w.\-]+/g, "_").slice(-80);
  const hasExt = /\.[a-z0-9]{1,8}$/i.test(base);
  return hasExt ? base : `${base}.${fallbackExt}`;
}
// Schritt 2: Dateigröße in menschenlesbarer Kurzform.
function _prettySize(n) {
  if (!Number.isFinite(n) || n <= 0) return "unbekannte Größe";
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / 1024 / 1024).toFixed(1)} MB`;
}
// Schritt 3: Telegram-Datei per rohem GET (Bot-Token) in ein lokales Verzeichnis speichern.
async function _saveTelegramFile(file, dir, fallbackExt) {
  if (!file || !file.file_path) throw new Error("getFile lieferte keinen file_path");
  const url = `https://api.telegram.org/bot${cfg.telegram.token}/file/bot/${file.file_path}`;
  const resp = await fetch(url);
  if (!resp.ok) throw new Error(`Medien-Download ${file.file_path} fehlgeschlagen: HTTP ${resp.status}`);
  const buf = Buffer.from(await resp.arrayBuffer());
  if (buf.length === 0) throw new Error("Medien-Download lieferte 0 Bytes");
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const path = path.join(dir, _mediaFilename(file, fallbackExt));
  fs.writeFileSync(path, buf);
  log(`medien gespeichert: ${path} (${_prettySize(buf.length)})`);
  return { path, size: buf.length };
}
// Schritt 4: multipart/form-data-Body manuell bauen (keine Abhängigkeit – FormData/Fetch-Body nicht verfügbar im Zero-Dep-Pfad).
function _toMultipart(fields, fileField) {
  const boundary = `----TGBot${Date.now().toString(16)}`;
  const parts = [];
  for (const [k, v] of fields) {
    if (v === undefined || v === null) continue;
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="${k}"\r\n\r\n${v}\r\n`, "utf8"));
  }
  const { filename, contentType, data } = fileField;
  parts.push(Buffer.from(
    `--${boundary}\r\nContent-Disposition: form-data; name="media"; filename="${filename}"\r\nContent-Type: ${contentType}\r\n\r\n`,
    "utf8"
  ));
  parts.push(data);
  parts.push(Buffer.from(`\r\n--${boundary}--\r\n`, "utf8"));
  return { body: Buffer.concat(parts), contentType: `multipart/form-data; boundary=${boundary}` };
}
// Schritt 5: Speicherverzeichnisse sicherstellen (idempotent, einmalig beim ersten Medien-Eintrag).
let _mediaDirsReady = false;
function ensureMediaDirs() {
  if (_mediaDirsReady) return;
  for (const p of [
    path.join(VAULT, "07_Recherche/Telegram-Medien/photos"),
    path.join(VAULT, "07_Recherche/Telegram-Medien/videos"),
    path.join(VAULT, "07_Recherche/Telegram-Medien/documents"),
    path.join(VAULT, "09_Prompts/Telegram-Voice"),
  ]) {
    if (!fs.existsSync(p)) fs.mkdirSync(p, { recursive: true });
  }
  _mediaDirsReady = true;
  log("medien-Verzeichnisse bereit");
}
// Schritt 6: Foto-Handler – größtes Foto-Size-Objekt nehmen, speichern, per multipart zurücksenden.
async function _handlePhoto(m, chatId, caption) {
  ensureMediaDirs();
  const sizes = m.photo || [];
  if (sizes.length === 0) return;
  const best = sizes.reduce((a, b) => ((b.file_size || 0) > (a.file_size || 0) ? b : a));
  const { file_id } = best;
  const meta = await tgApi("getFile", { file_id });
  if (!meta.ok) throw new Error(`getFile für ${file_id}: ${meta.description || "unbekannter Fehler"}`);
  const saved = await _saveTelegramFile(meta.result, path.join(VAULT, "07_Recherche/Telegram-Medien/photos"), "jpg");
  const mp = _toMultipart({ chat_id: chatId, caption: `${caption}\n[gespeichert: ${saved.path} (${_prettySize(saved.size)})]` },
    { filename: "photo.jpg", contentType: "image/jpeg", data: fs.readFileSync(saved.path) });
  await tgApiRaw("sendPhoto", mp);
  log(`foto gesendet + gespeichert (${saved.path})`);
}
// Schritt 7: Video-/Dokument-Handler – gemeinsame Speicheroptik, nur Ordner + Feldname unterscheiden sich.
async function _handleBigFile(m, chatId, caption, kind) {
  ensureMediaDirs();
  const src = kind === "video" ? m.video : m.document;
  const { file_id } = src;
  const meta = await tgApi("getFile", { file_id });
  if (!meta.ok) throw new Error(`getFile für ${file_id}: ${meta.description || "unbekannter Fehler"}`);
  const dir = path.join(VAULT, `07_Recherche/Telegram-Medien/${kind === "video" ? "videos" : "documents"}`);
  const saved = await _saveTelegramFile(meta.result, dir, kind === "video" ? "mp4" : "bin");
  const isVideo = kind === "video";
  const mp = _toMultipart(
    { chat_id: chatId, caption: `${caption}\n[gespeichert: ${saved.path} (${_prettySize(saved.size)})]` },
    { filename: path.basename(saved.path), contentType: isVideo ? "video/mp4" : "application/octet-stream", data: fs.readFileSync(saved.path) }
  );
  await tgApiRaw(isVideo ? "sendVideo" : "sendDocument", mp);
  log(`${kind} gesendet + gespeichert (${saved.path})`);
}
// Schritt 8: Voice-Handler – .ogg nach 09_Prompts/Telegram-Voice/, Transkription folgt nach Grundsatzentscheidung.
async function _handleVoice(m, chatId, caption) {
  ensureMediaDirs();
  const { file_id } = m.voice;
  const meta = await tgApi("getFile", { file_id });
  if (!meta.ok) throw new Error(`getFile für ${file_id}: ${meta.description || "unbekannter Fehler"}`);
  const saved = await _saveTelegramFile(meta.result, path.join(VAULT, "09_Prompts/Telegram-Voice"), "ogg");
  const mp = _toMultipart(
    { chat_id: chatId, caption: `${caption}\n[gespeichert: ${saved.path} (${_prettySize(saved.size)}) – Transkription folgt nach Whisper-Entscheidung]` },
    { filename: path.basename(saved.path), contentType: "audio/ogg", data: fs.readFileSync(saved.path) }
  );
  await tgApiRaw("sendVoice", mp);
  log(`voice gesendet + gespeichert (${saved.path})`);
}
