async function downloadMedia(chatId, fileId) {
  const url = CFG.telegram.baseUrl.replace('{token}', process.env.TELEGRAM_BOT_TOKEN || '');
  const fetchUrl = `${url}/file/bot/${process.env.TELEGRAM_BOT_TOKEN}/${fileId}`;
  const r = await fetch(fetchUrl);
  if (!r.ok) throw new Error(`Download failed ${r.status}`);
  return Buffer.from(await r.arrayBuffer());
}

function saveMediaFile(data, subdir, filename) {
  const dir = path.join(ROOT, 'public', 'media', subdir);
  fs.mkdirSync(dir, { recursive: true });
  const out = path.join(dir, filename);
  fs.writeFileSync(out, data);
  return out;
}

function buildMultipart(parts) {
  const boundary = '----AIv4Media' + Date.now().toString(36);
  const body = [];
  for (const p of parts) {
    body.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="${p.name}"`));
    if (p.filename) body.push(Buffer.from(`; filename="${p.filename}"\r\nContent-Type: ${p.mimeType || 'application/octet-stream'}\r\n`));
    else body.push(Buffer.from('\r\n'));
    body.push(p.data);
    body.push(Buffer.from('\r\n'));
  }
  body.push(Buffer.from(`--${boundary}--\r\n`));
  return { boundary, data: Buffer.concat(body) };
}

async function sendMediaWithCaption(chatId, caption, files, replyTo) {
  const token = process.env.TELEGRAM_BOT_TOKEN || '';
  const base = CFG.telegram.baseUrl.replace('{token}', token);
  const multi = buildMultipart(files);
  // Send caption first so we get a message_id for replies
  const capR = await fetch(`${base}/sendMessage`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: String(chatId), text: caption, ...(replyTo ? { reply_to_message_id: replyTo } : {}) })
  });
  const capJson = await capR.json().catch(() => null);
  const msgId = capJson?.message_id;
  // Then send each media as multipart
  for (const f of files) {
    try {
      const fr = await fetch(`${base}/sendPhoto`, {
        method: 'POST',
        headers: { 'Content-Type': `multipart/form-data; boundary=${multi.boundary}` },
        body: multi.data,
        signal: AbortSignal.timeout(60000)
      });
      const fj = await fr.json().catch(() => null);
      log('MEDIA-SEND', f.name, fj?.ok ? 'ok' : JSON.stringify(fj).slice(0, 200));
    } catch (e) { log('MEDIA-FAIL', f.name, e.message); }
  }
  return msgId;
}

