const MEDIA_DIR = path.join(ROOT, '..', '07_Recherche', 'Telegram-Medien');
const VOICE_DIR = path.join(ROOT, '..', '09_Prompts', 'Telegram-Voice');

function ensureDir(dir) { fs.mkdirSync(dir, { recursive: true }); }

async function downloadMedia(filePath, chatId, messageId) {
  const url = `https://api.telegram.org/bot${process.env.TELEGRAM_BOT_TOKEN}/file?file_path=${encodeURIComponent(filePath)}`;
  return new Promise((resolve, reject) => {
    https.get(url, res => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return https.get(res.headers.location, resolve);
      }
      if (res.statusCode !== 200) return reject(new Error(`Download-Fehler ${res.statusCode}`));
      resolve(res);
    }).on('error', reject);
  }).then(res => new Promise((resolve, reject) => {
    const chunks = [];
    res.on('data', c => chunks.push(c));
    res.on('end', () => resolve(Buffer.concat(chunks)));
    res.on('error', reject);
  }));
}

function saveMediaFile(buffer, mimeType, subfolder, originalName) {
  ensureDir(MEDIA_DIR);
  ensureDir(VOICE_DIR);
  const dir = subfolder === 'voice' ? VOICE_DIR : path.join(MEDIA_DIR, subfolder);
  ensureDir(dir);
  const ext = mimeType ? (/\/([a-z0-9]+)$/).exec(mimeType)?.[1] : 'bin';
  const safeName = (originalName || `media_${Date.now()}`).replace(/[^\w.-]/g, '_');
  const fname = `${safeName}.${ext}`;
  const full = path.join(dir, fname);
  let counter = 1;
  while (fs.existsSync(full)) {
    fs.writeFileSync(full.replace(`.${ext}`, `_(${counter}).${ext}`), buffer);
    counter++;
  }
  fs.writeFileSync(full, buffer);
  log('gespeichert:', full);
  return full;
}

async function sendMediaWithCaption(chatId, buffer, mimeType, caption) {
  const boundary = '----BotBoundary' + Date.now();
  const body = [
    `--${boundary}`,
    `Content-Disposition: form-data; name="chat_id"`,
    '',
    String(chatId),
    `--${boundary}`,
    `Content-Disposition: form-data; name="photo"`,
    `Content-Type: ${mimeType || 'application/octet-stream'}`,
    '',
    buffer.toString('base64'),
    `--${boundary}--`,
  ].join('\r\n');
  await tgApi('sendPhoto', { chat_id: chatId, photo: buffer, caption }, 15000);
}

async function handleMediaMessage(chatId, m) {
  const { photo, video, voice, document } = m;
  let filePath, mimeType, type, originalName;
  if (photo) {
    // Größtes Foto nehmen (letztes = höchste Auflösung)
    const best = photo[photo.length - 1];
    filePath = best.file_path;
    mimeType = 'image/jpeg';
    type = 'photos';
    originalName = best.file_unique_id;
  } else if (video) {
    filePath = video.file_path;
    mimeType = video.mime_type || 'video/mp4';
    type = 'videos';
    originalName = video.file_name || video.file_unique_id;
  } else if (voice) {
    filePath = voice.file_path;
    mimeType = voice.mime_type || 'audio/ogg';
    type = 'voice';
    originalName = voice.file_unique_id;
  } else if (document) {
    filePath = document.file_path;
    mimeType = document.mime_type || 'application/octet-stream';
    type = 'documents';
    originalName = document.file_name;
  } else return null;

  if (!filePath) return null;

  try {
    log('downloade Media:', type, filePath);
    const buf = await downloadMedia(filePath, chatId, m.message_id);
    const savedPath = saveMediaFile(buf, mimeType, type, originalName);
    const relPath = savedPath.replace(path.join(ROOT, '..'), '.');
    const caption = `📎 ${type.toUpperCase()} gespeichert:\n${relPath}\nID: ${m.message_id}`;

    if (type === 'voice') {
      // Voice direkt als Document zurückschicken
      await tgApi('sendDocument', { chat_id: chatId, document: buf, caption, parse_mode: 'HTML' });
    } else {
      await tgApi('sendPhoto', { chat_id: chatId, photo: buf, caption, parse_mode: 'HTML' });
    }
    return { savedPath, type };
  } catch (e) {
    log('MEDIA-FEHLER:', e.message);
    await deliver(chatId, `❌ Media-Fehler: ${e.message}`);
    return null;
  }
}

