127: async function deliver(chatId, text, replyTo) {
128:   const clean = String(text || '').trim() || '(leere Antwort)';
129:   const buf = Buffer.from(clean, 'utf8');
130:   const totalBytes = buf.length;
131:   const MAX = 4096;
132:   const chunks = [];
133:   for (let off = 0; off < totalBytes; off += MAX) {
134:     chunks.push(buf.subarray(off, off + MAX));
135:   }
136:   const chunkCount = chunks.length;
137:   for (let i = 0; i < chunkCount; i++) {
138:     let payload = '';
139:     if (chunkCount > 1) {
140:       // Ersten Byte-Chunk sicher in UTF-8 decoden; Rest als Buffer direkt ansenden via raw send nicht möglich – also alles über Text-Kanal
141:       // Wir encodieren jeden Chunk einzeln und senden als Text, weil Telegram sendMessage nur Text akzeptiert.
142:       // Header für Fortsetzungen: "(Fortsetzung k/N)" – ASCII-safe Prefix.
143:       const prefix = i === 0 ? '' : `(Fortsetzung ${i + 1}/${chunkCount})\n`;
144:       try {
145:         payload = prefix + chunks[i].toString('utf8');
146:       } catch {
147:         payload = prefix + '[unkorrigierbarer Chunk]';
148:       }
149:     } else {
150:       payload = chunks[i].toString('utf8');
151:     }
152:     try {
153:       await tgApi('sendMessage', { chat_id: chatId, text: payload, ...(replyTo ? { reply_to_message_id: replyTo } : {}) }, 20000);
154:     } catch (e) { log('SEND-FAIL', e.message); }
155:     if (i < chunkCount - 1) await sleep(300);
156:   }
157: }
