167: async function downloadMedia(filePath, chatId, messageId) {
168:   const url = `https://api.telegram.org/bot${process.env.TELEGRAM_BOT_TOKEN}/file?file_path=${encodeURIComponent(filePath)}`;
169:   return new Promise((resolve, reject) => {
170:     https.get(url, res => {
171:       if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
172:         return https.get(res.headers.location, resolve);
173:       }
174:       if (res.statusCode !== 200) return reject(new Error(`Download-Fehler ${res.statusCode}`));
175:       resolve(res);
176:     }).on('error', reject);
177:   }).then(res => new Promise((resolve, reject) => {
178:     const chunks = [];
179:     res.on('data', c => chunks.push(c));
180:     res.on('end', () => resolve(Buffer.concat(chunks)));
181:     res.on('error', reject);
182:   }));
183: }
