358: function runOpencode(job) {
359:   return new Promise((resolve, reject) => {
360:     const routeDef = CFG.routes[job.route] || CFG.routes.default;
361:     const dirAbs = path.isAbsolute(routeDef.dir) ? routeDef.dir : path.join(CFG.workspace, routeDef.dir || '.');
362:     const cwd = fs.existsSync(dirAbs) ? dirAbs : CFG.workspace;
363:     const session = state.sessions[job.route] || '';
364: 
365:     const args = ['run', '--format', 'json'];
366:     if (CFG.opencode?.auto !== false) args.push('--auto');
367:     if (routeDef.model) args.push('--model', routeDef.model);
368:     if (session) args.push('--session', session);
369:     args.push('--title', String(job.text || '').slice(0, 60) || 'AI-SYSTEM');
370:     args.push(String(job.text || ''));
371: 
372:     const child = spawn(CFG.opencodeExe, args, {
373:       cwd, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'],
374:       env: { ...process.env, OPENCODE_CONFIG: CFG.opencodeConfig }
375:     });
376: 
377:     let settled = false, stdout = '', stderr = '';
378:     const tokens = setTimeout(() => {
379:       if (settled) return; settled = true;
380:       try { spawn('taskkill', ['/PID', String(child.pid), '/T', '/F'], { windowsHide: true }); } catch { child.kill('SIGKILL'); }
381:       reject(new Error(`opencode Timeout nach ${CFG.routeTimeoutSec}s`));
382:     }, (CFG.routeTimeoutSec || 900) * 1000);
383:     child.unref?.();
384: 
385:     child.stdout.on('data', d => stdout += d);
386:     child.stderr.on('data', d => stderr += d);
387:     child.on('error', e => { if (settled) return; settled = true; clearTimeout(tokens); reject(e); });
388:     child.on('close', code => {
389:       if (settled) return; settled = true; clearTimeout(tokens);
390:       let newSession = '', texts = [];
391:       for (const line of stdout.split(/\r?\n/)) {
392:         const l = line.trim();
393:         if (!l.startsWith('{')) continue;
394:         try {
395:           const ev = JSON.parse(l);
396:           if (ev.sessionID && !newSession) newSession = String(ev.sessionID);
397:           if (ev.type === 'text' && ev.part && typeof ev.part.text === 'string') texts.push(ev.part.text);
398:         } catch { /* kein json */ }
399:       }
400:       if (newSession) state.sessions[job.route] = newSession;
401:       const answer = texts.join('').trim();
402:       if (code !== 0) { reject(new Error(`opencode exit ${code}: ${(stderr || stdout).slice(0, 300)}`)); return; }
403:       if (!answer) { reject(new Error('opencode lieferte keinen Text (' + stdout.trim().slice(0, 160) + ')')); return; }
404:       resolve(answer);
405:     });
406:   });
407: }
