const token = process.env.TELEGRAM_BOT_TOKEN || '7744634486:AAHWG2nXf8jTQz0fF5aZvRqP8dU6bK9mHxY';
const https = require('https');

function getUpdates() {
  return new Promise((resolve, reject) => {
    https.get(`https://api.telegram.org/bot${token}/getUpdates?timeout=10`, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const parsed = JSON.parse(data);
          resolve(parsed);
        } catch(e) {
          reject(new Error(`JSON parse failed: ${data}`));
        }
      });
    }).on('error', reject);
  });
}

async function run() {
  console.log('Polling updates...');
  const result = await getUpdates();
  console.log('Result:', JSON.stringify(result, null, 2));
  if (result.result && result.result.length > 0) {
    console.log(`\n✓ ${result.result.length} Update(s) gefunden!`);
    result.result.forEach((u, i) => {
      console.log(`\nUpdate ${i+1}:`);
      console.log('  update_id:', u.update_id);
      if (u.message) {
        console.log('  chat_id:', u.message.chat?.id);
        console.log('  from:', u.message.from?.username || u.message.from?.first_name);
        console.log('  text:', u.message.text);
        console.log('  photo:', u.message.photo?.length || 0);
        console.log('  video:', !!u.message.video);
        console.log('  voice:', !!u.message.voice);
        console.log('  document:', !!u.message.document);
      }
    });
  } else {
    console.log('\n✗ Keine Updates – sende jetzt ein Foto an @dirkb_bot');
  }
}

run().catch(console.error);

