        $('c-running').textContent = c.running ?? 0;
        $('c-done').textContent = c.done ?? 0;
        $('c-failed').textContent = c.failed ?? 0;
        const tg = s.telegram || {};
        const chip = $('tg-chip');
        if (tg.running) {
          chip.textContent = 'l�uft';
          chip.className = 'chip on';
          $('tg-detail').textContent = '';
