          chip.className = 'chip off';
          $('tg-detail').textContent = tg.lastError ? '� ' + tg.lastError : '';
        } else {
          chip.textContent = 'aus';
          chip.className = 'chip off';
          $('tg-detail').textContent = '';
        }
