          '<span class="badge ' + esc(j.status) + '">' + esc(j.status) + '</span>' +
          '<span class="route">@' + esc(j.route) + '</span>' +
          '<span class="when">' + esc(relTime(j.createdAt)) + '</span>' +
        '</div>' +
        '<div class="id">' + esc(String(j.id || '').slice(0, 8)) + '</div>' +
        '<p class="text">' + esc(String(j.body || '').slice(0, 160)) + '</p>';
      return el;
    }

    async function refreshJobs() {
