        const data = await fetchJSON('/api/jobs');
        const list = (Array.isArray(data.jobs) ? data.jobs : []).slice(0, 15);
        const box = $('jobs');
        box.innerHTML = '';
        if (!list.length) {
          box.innerHTML = '<p class="empty">Noch keine Jobs - schau am Handy vorbei.</p>';
          return;
        }
        const frag = document.createDocumentFragment();
        for (const j of list) frag.appendChild(jobCard(j));
        box.appendChild(frag);
      } catch (e) { /* still - Offline-Badge reicht */ }
    }

    function refreshAll() {
      refreshStatus();
      refreshJobs();
    }

    refreshAll();
    setInterval(refreshAll, 10000);

    // Service Worker registrieren (nur HTTPS bzw. localhost - sonst getDataFromError ignorieren)
