220:     proc.stderr.on('data', d => stderr += d);
221:     proc.on('close', code => code === 0 ? resolve(outPath) : reject(new Error(`FFmpeg Exit ${code}: ${stderr}`)));
222:     proc.on('error', reject);
223:   });
224:   return outPath;
225: }
